INSERT INTO "emailtemplates" ("id","TemplateName","TemplateText","Subject","SenderName","SenderEmail","AlertChannel","AlertLanguageCode","Alert_id") VALUES ('21','BUSINESS_ENROLLMENT_REJECTED_TEMPLATE',TO_CLOB('<!DOCTYPE html><html> <head> <link href="http://fonts.googleapis.com/css?family=Lato:400,700" rel="stylesheet" type="text/css"> <style>body {font-family: "Lato";}</style> </head> <body bgcolor= "#ebecee"> <center> <div style="width:95%; height: 10px; margin: 50px 0px 0px 0px;"> <div> <table height="100%" width="100%" cellpadding="0" cellspacing="0" border="0"> <!--[if mso]> <center> <tr> <td> <div> <table border="0" cellpadding="0" cellspacing="0" width="95%"> <![endif]--> <tr> <td align="center" valign="top" height="10" bgcolor="#284e77" style="background-color:#284e77;font-size:1px;line-height:1px; -webkit-text-size-adjust:none;">&nbsp;</td> </tr> </table> <!--[if mso]> </div> </td> </tr> </center> </table> <![endif]--> </div> </div> <div style="width:95%; margin: 0px 0px 50px 0px;"> <div style="display: inline-block; text-align: left;"> <table height="100%" width="100%" cellpadding="0" cellspacing="0" border="0"> <!--[if mso]> <center> <tr> <td> <div> <table border="0" cellpadding="0" cellspacing="0" width="95%"> <![endif]--> <tr> <td style="background-color:#ffffff; -webkit-text-size-adjust:none;"> <div style="margin: 50px 20px 50px 20px; color: #333b44; font-size: 13px;"> <!--[if mso]> <font face="Lato"> <![endif]--> <span style="margin: 10% 0% 5% 0%;"> <table style="width: 50%;" width="50%"> <tr> <td width="200"> <!--[if mso]> <table width="200"> <tr> <td> <img width="200" src="emailTemplateLogo" alt="kony_logo" style="text-align: right; width: 200px; border: 0;"> </td> </tr> </table> <div style="display:none"> <![endif]--><img style="text-align: right; width: 200px; border: 0;" src="https://retailbanking1.konycloud.com/dbimages/infinitydbxlogo.png" alt="temenos_logo" width="200" /> <!--[if mso]> </div> <![endif]--> </td> <!-- <td style="font-size:28px;