INSERT INTO "emailtemplates" ("id","TemplateName","TemplateText","Subject","SenderName","SenderEmail","AlertChannel","AlertLanguageCode","Alert_id") VALUES ('22','ENROLLMENT_USERNAME_TEMPLATE',TO_CLOB('<p>&nbsp;</p><center><div style="width: 95%; height: 5px; margin: 0px 0px 0px 0px;"><div><table border="0" width="100%" cellspacing="0" cellpadding="0"><tbody><tr><td style="background-color: #284e77; font-size: 1px; line-height: 1px; -webkit-text-size-adjust: none;" align="center" valign="top" bgcolor="#284e77" height="10">&nbsp;</td></tr></tbody></table></div></div><div style="width: 95%; margin: 0px 0px 50px 0px;"><div style="display: inline-block; text-align: left;"><table style="width: 50%;" width="50%"><tbody><tr><td width="200"><img style="text-align: right; width: 200px; border: 0;" src="https://retailbanking1.konycloud.com/dbimages/infinitydbxlogo.png" alt="temenos_logo" width="200" /></td></tr></tbody></table> <br /><br />Hi %firstName% %lastName%,<br /><br />You are enrolled to Digital Banking Channel. Please activate your account now.<br /><br />%userName% is your username. Activation code is sent to you registered mobile number.<br /><br />You are required to input your username &amp; activation code in the link below.<br /><br /><div style="text-align: center; border-width: 1px; border-radius: 4px;"><table style="table-layout: fixed;" border="0" width="100%" cellspacing="0" cellpadding="0"><tbody><tr><td style="color: #ffffff; background-color: #333b44; word-wrap: break-word; word-break: break-all; padding: 10px; line-height: 20px;" align="center"><div style="margin: 10px 10px 10px 10px; font-size: 13px;">To activate your account and set a password,<a style="color: #11abeb;" href="%resetPasswordLink%">click here</a> <br />or paste the following link on your browser: <br /><br /><a style="color: #11abeb;">%resetPasswordLink%</a></div></td></tr></tbody></table></div> <br /><center>The activation code will expire in %activationCodeExpiry% days , so activate it right away.</center><br /><br />Regards,<br />Temenos Banking Team <br /><br /><br /><br /><span style="color: #999999; font-size: 12px;">This is a system generated mail. If you are not the named addressee please notify the sender immediately by e-mail at support@temenosbank.com and then delete the e-mail from your system. Although the company has taken reasonable precautions to ensure no viruses are present in this email, the company cannot accept responsibility for any loss or damage arising from the use of this email or attachments. Temenos, Inc. www.temenos.com </span><br /><br /><div align="center"><span style="color: #999999;"><strong>(c) Copyright Infinity Retail Origination</strong>. All rights reserved.</span></div></div></div></center>'),'Account Activation','Infinity','dbx_cl@infinity.com',NULL,NULL,NULL);
INSERT INTO "emailtemplates" ("id","TemplateName","TemplateText","Subject","SenderName","SenderEmail","AlertChannel","AlertLanguageCode","Alert_id") VALUES ('23','ENROLLMENT_ACTIVATIONCODE_TEMPLATE',TO_CLOB('Dear Customer, You are enrolled to digital banking channel. %otp% is your activation code. Use it to activate your profile. Username & activation link are sent to your registered email'),'Account Activation','Infinity','dbx_cl@infinity.com',NULL,NULL,NULL);
INSERT INTO "emailtemplates" ("id","TemplateName","TemplateText","Subject","SenderName","SenderEmail","AlertChannel","AlertLanguageCode","Alert_id") VALUES ('24','APPLICANT_RESUME_ONBOARDING_APPLICATION_NEWUSER',TO_CLOB('<html> <head></head> <body> <table border="0" width="100%" cellspacing="0" cellpadding="0" align="center" bgcolor="#FFFFFF"> <tbody> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 14px 24px; border-bottom: 3px solid #0A78D1; font-family: sans-serif; font-weight: 400;"><img style="display: inline-blaock; float: left; vertical-align: middle;" src="https://i.imgur.com/YWp6idv.png" alt="logo"></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 25px 23px 0 23px; font-family: sans-serif; font-weight: 400;"><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Welcome</span><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">&nbsp;</span><span style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">%FirstName% %LastName%!</span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Thank you for applying for an Infinity account.</span></td> </tr><tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;"> <p><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Please use the credentials we send in the email and on your mobile to resume your application. </span></p> </td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;"> <p><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">To finish your application, click here to <a href="%ResumeLink%">continue</a>. </span></p> </td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 20px 23px 0 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Your username is  : <strong>%UserName%</strong></span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 1px 23px 0 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Application number : <strong>%ApplicationId%</strong></span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 1px 23px 30px 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Created on : <strong>%StartDate%</strong></span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 0 23px 0 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Sincerely, </span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 4px 23px 27px 23px; font-family: sans-serif; font-weight: 300; border-bottom: 1px solid #0A78D1;"><span style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">Infinity Bank</span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 17px 23px 0px 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: san')||TO_CLOB('s-serif; font-size: 11px; font-weight: 400; line-height: 13px; color: #000000; display: inline-block;">This is a system generated mail. Please do not reply to this e-mail address.</span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 7px 23px 0px 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">Have any questions?</span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 7px 23px 0px 23px; font-family: sans-serif; font-weight: 300;"> <div style="width: 100%; display: inline-block; padding: 18px 11px; vertical-align: middle; text-align: left; border-radius: 3px; border: 1px solid #E6E6E6; background-color: #ffffff;"><span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">Call us at</span> <span style="font-family: sans-serif; font-size: 12px; font-weight: bold; line-height: 14px; color: #000000; display: inline-block;">&nbsp;1-800-412-5434&nbsp;</span> <span style="font-family: sans-serif; font-size: 12px; font-weight: 400; line-height: 14px; color: #000000; display: inline-block;">for assistance.</span></div> </td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 17px 23px 0px 23px; font-family: sans-serif; font-weight: 300;"><span style="font-family: sans-serif; font-size: 10px; font-weight: 400; line-height: 12px; color: #000000; display: inline-block;">CONFIDENTIALITY INFORMATION AND DISCLAIMER</span></td> </tr> <tr> <td style="width: 100%; vertical-align: middle; text-align: left; padding: 5px 23px 18px 23px